parameters.customBody:
={{ (() => {
  const s = $('Set your pitch').first().json;
  const list = v => String(v || '').split(',').map(x => x.trim()).filter(Boolean);
  return JSON.stringify({
    keywords: list(s.niches),
    requireEmail: true,
    guestFriendlyOnly: true,
    activeWithinDays: s.activeWithinDays,
    country: s.country,
    maxPodcasts: s.maxShows,
    onlyNewPodcasts: true
  });
})() }}

