assignments.value:
={{ (() => {
const o = $json.output;
const title = String($('Skip shows already seen').item.json.podcastName || '').toLowerCase();
const points = String($('Set your pitch').first().json.talkingPoints || '').toLowerCase();
const w = String(o.titleWord || '').trim().toLowerCase();
const inTitle = w.length > 2 && title.includes(w) && points.includes(w);
const fit = Number(o.fit) || 0;
return inTitle ? fit : Math.min(fit, 70);
})() }}

