parameters.message:
={{ (() => {
const ascii = t => String(t ?? '').replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/[\u2013\u2014]/g, '-').replace(/\u2026/g, '...').replace(/\u00a0/g, ' ');
const tidy = t => ascii(t).split('\n').map(l => l.replace(/[ \t]+$/, '')).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const out = tidy($json.text);
const nl = out.indexOf('\n');
return tidy(nl === -1 ? out : out.slice(nl + 1));
})() }}

parameters.subject:
={{ (() => {
const out = String($json.text || '').trim();
const nl = out.indexOf('\n');
const first = nl === -1 ? out : out.slice(0, nl);
return first.replace(/^subject:\s*/i, '').trim();
})() }}

parameters.text:
={{ (() => {
const esc = s => String(s ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const cut = (s, n) => String(s ?? '').length > n ? String(s).slice(0, n - 1).trimEnd() + '\u2026' : String(s ?? '');
const r = $('Format the show row').item.json;
const ascii = t => String(t ?? '').replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/[\u2013\u2014]/g, '-').replace(/\u2026/g, '...').replace(/\u00a0/g, ' ');
const tidy = t => ascii(t).split('\n').map(l => l.replace(/[ \t]+$/, '')).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const out = tidy($('Write the pitch email').item.json.text);
const nl = out.indexOf('\n');
const subject = (nl === -1 ? '' : out.slice(0, nl)).replace(/^subject:\s*/i, '').trim();
const body = tidy(nl === -1 ? out : out.slice(nl + 1));
return '\ud83c\udf99 <b>' + esc(r['Show']) + '</b> \u00b7 fit ' + r['Fit'] + '/100\n'
  + '\ud83d\udc64 ' + esc(r['Host'] || 'host not named') + ' \u00b7 ' + esc(r['Email']) + '\n'
  + '\ud83e\udde9 ' + esc(r['Why it fits']) + '\n'
  + '\ud83c\udfac ' + esc(r['Proposed episode']) + '\n'
  + '\ud83d\udcc5 ' + r['Episodes'] + ' episodes \u00b7 last one ' + r['Days since last episode'] + ' days ago\n\n'
  + (subject ? '<b>Subject</b>\n' + esc(subject) + '\n\n' : '')
  + '<b>Draft in your Gmail, read it before you send</b>\n<pre>' + esc(cut(body, 2600)) + '</pre>\n\n'
  + '\u27a1 <a href="' + r['Apple link'] + '">The show on Apple Podcasts</a>';
})() }}
